      if ((activeTool === 'pen' || activeTool === 'highlighter') && liveStroke.length >= 2) {
        const newObj = {
          id: 'stroke_' + Date.now(),
          type: activeTool,
          points: liveStroke,
          color: currentColor,
          strokeWidth: strokeWidth,
          createdAt: Date.now()
        };
        commitObject(newObj);
      }
